using Cosmos.Application.Abstractions.Persistence;using Cosmos.Application.Abstractions.Services;using Cosmos.Application.Organization;using Cosmos.Contracts.Audit;using Cosmos.Contracts.Organization;using Cosmos.Shared.Exceptions;using Cosmos.Shared.Responses;using Cosmos.Shared.Security;
namespace Cosmos.Application.Services;
public sealed class CompanyBranchMasterService(ICompanyBranchMasterRepository repo,IAuditRepository audit,ICurrentUser user):ICompanyBranchMasterService { public async Task<ApiResponse<IReadOnlyCollection<CompanyDto>>> CompaniesAsync(string? s,bool a,CancellationToken ct)=>ApiResponse<IReadOnlyCollection<CompanyDto>>.Success(await repo.CompaniesAsync(s,a,ct)); public async Task<ApiResponse<CompanyDto>> CompanyAsync(long id,CancellationToken ct)=>ApiResponse<CompanyDto>.Success(await repo.CompanyAsync(id,ct)??throw new NotFoundException("Company was not found.")); public async Task<ApiResponse<CompanyDto>> SaveCompanyAsync(long? id,SaveCompanyRequest r,CancellationToken ct){if(string.IsNullOrWhiteSpace(r.Code)||string.IsNullOrWhiteSpace(r.Name))throw new CosmosException("Company code and name are required.",400);var old=id is null?null:await repo.CompanyAsync(id.Value,ct)??throw new NotFoundException("Company was not found.");var x=await repo.SaveCompanyAsync(id,r.Code.Trim(),r.Name.Trim(),r.IsActive,user.UserId,ct);await audit.AddAsync(new AuditEntryRequest("Companies",x.Id.ToString(),id is null?"Create":"Update",old is null?null:AuditSerializer.Serialize(old),AuditSerializer.Serialize(x),user.UserId),ct);return ApiResponse<CompanyDto>.Success(x);} public async Task<ApiResponse<IReadOnlyCollection<BranchDto>>> BranchesAsync(long? c,string? s,bool a,CancellationToken ct)=>ApiResponse<IReadOnlyCollection<BranchDto>>.Success(await repo.BranchesAsync(c,s,a,ct)); public async Task<ApiResponse<BranchDto>> BranchAsync(long id,CancellationToken ct)=>ApiResponse<BranchDto>.Success(await repo.BranchAsync(id,ct)??throw new NotFoundException("Branch was not found.")); public async Task<ApiResponse<BranchDto>> SaveBranchAsync(long? id,SaveBranchRequest r,CancellationToken ct){if(string.IsNullOrWhiteSpace(r.Code)||string.IsNullOrWhiteSpace(r.Name))throw new CosmosException("Branch code and name are required.",400);var company=await repo.CompanyAsync(r.CompanyId,ct)??throw new NotFoundException("Company was not found.");if(!company.IsActive)throw new CosmosException("Branch must belong to an active company.",409);var old=id is null?null:await repo.BranchAsync(id.Value,ct)??throw new NotFoundException("Branch was not found.");if(old is not null&&old.CompanyId!=r.CompanyId)throw new CosmosException("Branch company reassignment is not allowed.",409);var x=await repo.SaveBranchAsync(id,r.CompanyId,r.Code.Trim(),r.Name.Trim(),r.IsActive,user.UserId,ct);await audit.AddAsync(new AuditEntryRequest("Branches",x.Id.ToString(),id is null?"Create":"Update",old is null?null:AuditSerializer.Serialize(old),AuditSerializer.Serialize(x),user.UserId),ct);return ApiResponse<BranchDto>.Success(x);} }
